INSERT INTO clinical_reports(report_id,source_id,hazard_id,category,title,problem,content_text,symptoms_text,countermeasures_text,payload_json) VALUES ('hypercapnia_co2','NASA-EVA','HOSTILE_CLOSED_ENVIRONMENT','PHYSIOLOGICAL','Hipercapnia / exposição elevada a CO2','CO2 ambiental elevado pode exigir avaliação do sistema de suporte de vida e contexto de sintomas.','Referência de pesquisa/risco; não protocolo diagnóstico validado. Regras numéricas, priors e LRs são fixtures de engenharia. Entrevista contextual e registros de qualidade. SCD40 quando disponível; ausência permanece NULL. hypercapnia CO2','cefaleia headache dor de cabeça tontura fadiga falta de ar confusão náusea pele corada hipercapnia dizziness fatigue dyspnea confusion nausea flushed skin hypercapnia CO2 mal-estar dificuldade de concentração','Registrar contexto e conferir a qualidade das observações. Solicitar avaliação pelo protocolo médico autorizado para a missão. Conferir o sensor de CO2 e registrar o estado da ventilação para a equipe responsável pelo suporte de vida.','{"schema_version":1,"report_id":"hypercapnia_co2","source_id":"NASA-EVA","hazard_id":"HOSTILE_CLOSED_ENVIRONMENT","category":"PHYSIOLOGICAL","title":"Hipercapnia / exposição elevada a CO2","problem":"CO2 ambiental elevado pode exigir avaliação do sistema de suporte de vida e contexto de sintomas.","primary_symptoms":["cefaleia","headache","dor de cabeça","tontura","fadiga","falta de ar","confusão","náusea","pele corada","hipercapnia","dizziness","fatigue","dyspnea","confusion","nausea","flushed skin","hypercapnia","CO2"],"secondary_symptoms":["mal-estar","dificuldade de concentração"],"detection":["Entrevista contextual e registros de qualidade.","SCD40 quando disponível; ausência permanece NULL."],"scientific_scope":"Referência de pesquisa/risco; não protocolo diagnóstico validado. Regras numéricas, priors e LRs são fixtures de engenharia.","conditions":[{"condition_id":"HYPERCAPNIA","name":"Hipercapnia / exposição elevada a CO2","source_id":"NASA-EVA","subsystem":"RESPIRATORY_ATMOSPHERE","prior":0.05,"default_escalation":"CREW","recommended_mission_mode":"MODE_REST_VITALS","symptoms":["cefaleia","headache","mal-estar","dificuldade de concentração","dor de cabeça","tontura","fadiga","falta de ar","confusão","náusea","pele corada","hipercapnia","dizziness","fatigue","dyspnea","confusion","nausea","flushed skin","hypercapnia","CO2"],"countermeasures":["Registrar contexto e conferir a qualidade das observações.","Solicitar avaliação pelo protocolo médico autorizado para a missão.","Conferir o sensor de CO2 e registrar o estado da ventilação para a equipe responsável pelo suporte de vida."],"actions":["RECORD_CONTEXT","REQUEST_MEDICAL_REVIEW"],"linked_protocols":["environment_check"],"match_policy":"ALL","model_status":"ENGINEERING_TEST_ONLY","sensor_rules":[{"metric":"co2_ppm","op":"GT","threshold_value":3500,"source_sensor":"SCD40","values_json":{},"likelihood_ratio":3.0,"severity_tier":"YELLOW","weight_basis":"ENGINEERING_TEST_ONLY_NOT_CLINICALLY_VALIDATED","description":"Regra sintética de integração; requer validação clínica antes de uso decisório."}],"questions":[{"prompt":"A cefaleia acompanha CO2 elevado e melhora ao sair da área?","positive_concepts":["cefaleia","headache"],"yes_likelihood":0.85,"no_likelihood":0.15,"linked_protocol_id":"environment_check"}],"contraindications":[{"blocked_action":"CLOSE_VENTILATION","guard_metric":"co2_ppm","guard_op":"GT","guard_value":3500,"rationale":"Guarda de segurança do protótipo; revisão clínica e autorização da missão são necessárias. O limiar 500 de ferritina é um requisito de teste, não diagnóstico ou recomendação de dose."}]}],"legacy_reference":{"id":"HRP-RISK-CO2","source":{"document":"NASA Human Research Program (HRP), Human Research Roadmap - Risk of Adverse Health Effects from CO2; NASA-STD-3001 Vol. 1/2","section":"Atmosphere / CO2 limits","source_id":"NASA-HRP-CO2"},"detection":["I2C: SCD40 (CO2)","Respiração via CSI","Amsler normal 