rmeasures":["Registrar e revisar contexto antes de atribuir patologia."],"actions":["RECORD_CONTEXT"],"linked_protocols":["nutrition_review"],"subsystem":"IMMUNE_HEMATO_NUTRITION","questions":[{"prompt":"Houve exercício ARED recente?","positive_concepts":["ARED","exercício"],"yes_likelihood":0.85,"no_likelihood":0.15,"linked_protocol_id":"blood_pressure"}],"contraindications":[{"blocked_action":"UNREVIEWED_TREATMENT","guard_metric":"clinical_authorization","guard_op":"EQ","guard_value":0,"rationale":"Não iniciar tratamento a partir de um cenário sintético."}],"condition_id":"DEHYDRATION","name":"Hidratação reduzida por sete dias","sensor_rules":[{"metric":"water_7d_mean_ml","op":"LT","threshold_value":1200,"values_json":{},"source_sensor":"CONTEXT_AND_BASELINE","likelihood_ratio":3.0,"severity_tier":"YELLOW","weight_basis":"ENGINEERING_TEST_ONLY_NOT_CLINICALLY_VALIDATED","description":"Exercício e baseline individual contextualizam esta regra de teste."},{"metric":"nutrition_days_observed","op":"GE","threshold_value":7,"values_json":{},"source_sensor":"CONTEXT_AND_BASELINE","likelihood_ratio":3.0,"severity_tier":"YELLOW","weight_basis":"ENGINEERING_TEST_ONLY_NOT_CLINICALLY_VALIDATED","description":"Exercício e baseline individual contextualizam esta regra de teste."}],"source_id":"NASA-NUTRITION","model_status":"ENGINEERING_TEST_ONLY","match_policy":"ALL"}],"legacy_reference":{"id":"HRP-RISK-NUTRITION","source":{"document":"NASA Human Research Program (HRP), Human Research Roadmap - Risk of Inadequate Food and Nutrition; Nutrition SMO","section":"Evidence Report","source_id":"NASA-HRP-NUTRITION"},"detection":["Registro alimentar e hidratação","Autoexame: sangue capilar (glicemia)"]}}') ON CONFLICT(report_id) DO UPDATE SET source_id=excluded.source_id,hazard_id=excluded.hazard_id,category=excluded.category,title=excluded.title,problem=excluded.problem,content_text=excluded.content_text,symptoms_text=excluded.symptoms_text,countermeasures_text=excluded.countermeasures