":"MODE_REST_VITALS","symptoms":["marcador bioquímico alterado","alteração visual","visão turva","cefaleia","dor de cabeça","fadiga","formigamento","blurred vision","headache","fatigue","tingling","SANS","VIIP","B-complex","homocysteine"],"countermeasures":["Registrar contexto e conferir a qualidade das observações.","Solicitar avaliação pelo protocolo médico autorizado para a missão."],"actions":["RECORD_CONTEXT","REQUEST_MEDICAL_REVIEW"],"linked_protocols":["nutrition_review"],"match_policy":"ALL","model_status":"ENGINEERING_TEST_ONLY","sensor_rules":[{"metric":"one_carbon_review_required","op":"EQ","threshold_value":1,"source_sensor":"LAB","values_json":{},"likelihood_ratio":3.0,"severity_tier":"YELLOW","weight_basis":"ENGINEERING_TEST_ONLY_NOT_CLINICALLY_VALIDATED","description":"Regra sintética de integração; requer validação clínica antes de uso decisório."}],"questions":[{"prompt":"Há resultado bioquímico e avaliação nutricional para revisar a via de um carbono?","positive_concepts":["marcador bioquímico alterado"],"yes_likelihood":0.85,"no_likelihood":0.15,"linked_protocol_id":"nutrition_review"}],"contraindications":[{"blocked_action":"HIGH_DOSE_B_COMPLEX","guard_metric":"clinical_authorization","guard_op":"EQ","guard_value":0,"rationale":"Guarda de segurança do protótipo; revisão clínica e autorização da missão são necessárias. O limiar 500 de ferritina é um requisito de teste, não diagnóstico ou recomendação de dose."}]}],"legacy_reference":{"id":"HRP-RISK-ONE-CARBON","source":{"document":"NASA Human Research Program (HRP), Human Research Roadmap - Risk of SANS; one-carbon metabolism","section":"Evidence Report","source_id":"NASA-HRP-ONE-CARBON"},"detection":["Autoexame: Amsler e sangue capilar","CO2 normal"]}}') ON CONFLICT(report_id) DO UPDATE SET source_id=excluded.source_id,hazard_id=excluded.hazard_id,category=excluded.category,title=excluded.title,problem=excluded.problem,content_text=excluded.content_text,symptoms_text=excluded.symptoms_text,counte