OBEHAVIORAL_RADIATION","prior":0.03,"default_escalation":"CREW","recommended_mission_mode":"MODE_REST_VITALS","symptoms":["radiação","exposição cumulativa","dose acumulada","radiation","cumulative exposure","carcinogenesis","cancer risk","GCR"],"countermeasures":["Registrar exposição e contexto.","Aplicar apenas o procedimento autorizado e solicitar avaliação da equipe responsável."],"actions":["MEDICAL_REVIEW"],"linked_protocols":["symptom_review"],"match_policy":"ALL","model_status":"ENGINEERING_TEST_ONLY","sensor_rules":[{"metric":"radiation_long_term_review","op":"EQ","threshold_value":1,"source_sensor":"MISSION_CONTEXT","values_json":{},"likelihood_ratio":3.0,"severity_tier":"YELLOW","weight_basis":"ENGINEERING_TEST_ONLY_NOT_CLINICALLY_VALIDATED","description":"Sinal de teste para revisão contextual, não diagnóstico."}],"questions":[{"prompt":"Há contexto documentado para este risco?","positive_concepts":["radiação","exposição cumulativa","dose acumulada","radiation","cumulative exposure","carcinogenesis","cancer risk","GCR"],"yes_likelihood":0.85,"no_likelihood":0.15,"linked_protocol_id":"symptom_review"}],"contraindications":[{"blocked_action":"UNREVIEWED_TREATMENT","guard_metric":"clinical_authorization","guard_op":"EQ","guard_value":0,"rationale":"Não iniciar tratamento sem autorização clínica."}]}]}') ON CONFLICT(report_id) DO UPDATE SET source_id=excluded.source_id,hazard_id=excluded.hazard_id,category=excluded.category,title=excluded.title,problem=excluded.problem,content_text=excluded.content_text,symptoms_text=excluded.symptoms_text,countermeasures_text=excluded.countermeasures_text,payload_json=excluded.payload_json;
