ano","source_id":"NASA-SLEEP","subsystem":"NEUROBEHAVIORAL_RADIATION","prior":0.05,"default_escalation":"CREW","recommended_mission_mode":"MODE_REST_VITALS","symptoms":["sonolência","insônia","irritabilidade","cefaleia","fadiga","confusão","mal-estar","lesão cutânea","sono curto","hidratação baixa","fatigue","insomnia","headache","confusion","malaise","skin lesion","short sleep","low hydration","dehydration","cortisol","CRP"],"countermeasures":["Registrar contexto e conferir a qualidade das observações.","Solicitar avaliação pelo protocolo médico autorizado para a missão."],"actions":["RECORD_CONTEXT","REQUEST_MEDICAL_REVIEW"],"linked_protocols":["sleep_review"],"match_policy":"ALL","model_status":"ENGINEERING_TEST_ONLY","sensor_rules":[{"metric":"sleep_duration_h","op":"LT","threshold_value":5,"source_sensor":"LONGITUDINAL","values_json":{},"likelihood_ratio":3.0,"severity_tier":"YELLOW","weight_basis":"ENGINEERING_TEST_ONLY_NOT_CLINICALLY_VALIDATED","description":"Regra sintética de integração; requer validação clínica antes de uso decisório."}],"questions":[{"prompt":"O horário de sono ou iluminação mudou nos últimos dias?","positive_concepts":["sonolência","insônia"],"yes_likelihood":0.85,"no_likelihood":0.15,"linked_protocol_id":"sleep_review"}],"contraindications":[{"blocked_action":"UNREVIEWED_SEDATIVE","guard_metric":"clinical_authorization","guard_op":"EQ","guard_value":0,"rationale":"Guarda de segurança do protótipo; revisão clínica e autorização da missão são necessárias. O limiar 500 de ferritina é um requisito de teste, não diagnóstico ou recomendação de dose."}]}],"legacy_reference":{"id":"HRP-RISK-SLEEP","source":{"document":"NASA Human Research Program (HRP), Human Research Roadmap - Risk of Performance and Behavioral Health Decrements due to Inadequate Sleep/Circadian Misalignment; BMed","section":"Evidence Report","source_id":"NASA-HRP-BMed-IMMUNE"},"detection":["Arquitetura do sono e HRV via CSI (MODE_REST_VITALS)","Autoexame: temperatura e hidrat